/// A request to the `wifi` interface that passed the receiver's schema check.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Request {
    Scan,
    Join { ssid: List<u8, 32>, passphrase: Text<64>, remember: bool },
    Status,
    Leave,
    Forget { ssid: List<u8, 32> },
    Countries { from: u16 },
    Channels { code: Text<2> },
    Country,
    SetCountry { code: Text<2> },
}

/// Checks a received message against the schema (MC-2.4): method, major version, unused bits, capability kind, and
/// for buffer calls every length and value of a private copy of the request (MC-2.11). `cap` is the slot passed to
/// `recv`; an unexpected capability is dropped (MC-2.12). The `Call` is what the reply functions need.
pub fn decode(request: &Received, cap: usize) -> core::result::Result<(Request, Call), Reject> {
    let words = request.data;
    wire::header(request, cap, MAJOR)?;
    match words[0] & 0xFF {
        1 => {
            let mut copy = [0u8; 1];
            let (call, length) = wire::take_buffer(request, cap, 1474, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Scan, call))
        }
        2 => {
            let mut copy = [0u8; 101];
            let (call, length) = wire::take_buffer(request, cap, 0, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let ssid = <List<u8, 32> as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            let passphrase = <Text<64> as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            let remember = <bool as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Join { ssid, passphrase, remember }, call))
        }
        3 => {
            let mut copy = [0u8; 1];
            let (call, length) = wire::take_buffer(request, cap, 47, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Status, call))
        }
        4 => {
            wire::body(request, cap, [0x0, 0x0], CAP_KIND_NONE, false)?;
            Ok((Request::Leave, Call::words(request, cap)))
        }
        5 => {
            let mut copy = [0u8; 34];
            let (call, length) = wire::take_buffer(request, cap, 1, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let ssid = <List<u8, 32> as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Forget { ssid }, call))
        }
        6 => {
            let mut copy = [0u8; 2];
            let (call, length) = wire::take_buffer(request, cap, 196, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let from = <u16 as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Countries { from }, call))
        }
        7 => {
            let mut copy = [0u8; 4];
            let (call, length) = wire::take_buffer(request, cap, 194, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let code = <Text<2> as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Channels { code }, call))
        }
        8 => {
            let mut copy = [0u8; 1];
            let (call, length) = wire::take_buffer(request, cap, 29, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Country, call))
        }
        9 => {
            let mut copy = [0u8; 4];
            let (call, length) = wire::take_buffer(request, cap, 29, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let code = <Text<2> as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::SetCountry { code }, call))
        }
        _ => { wire::discard(request, cap); Err(Reject::Invalid) }
    }
}

pub fn reply_scan(call: Call, value: core::result::Result<&[Network], Error>) -> Result<()> {
    let value = match value { Ok(value) => value, Err(error) => return wire::reply_code(call, error as usize) };
    wire::reply_buffer(call, |w| codec::encode_slice::<Network, 32>(value, w))
}
